"use client";

import { useMemo, useState } from "react";
import { amount, beamQuantities, columnQuantities, footingQuantities, meshSteelKg, pileQuantities, safe, slabQuantities } from "@/lib/estimate-math";

type Rate = { material: number; labour: number; unit: string; label: string };
type RateKey = "rcc"|"steel"|"formwork"|"excavation"|"pcc"|"backfill"|"earthFill"|"sandFill"|"brickSoling"|"boring"|"pileHead"|"pileTest"|"waterproof";
type Rates = Record<RateKey, Rate>;
type CostLine = { section:string; subsection:string; item:string; unit:string; qty:number; materialRate:number; labourRate:number; amount:number };
type PreliminaryItem = { id:string; item:string; unit:string; qty:number; materialRate:number; labourRate:number };
type PileRow = { id:string; code:string; count:number; diameterIn:number; lengthFt:number; mainBars:number; mainDiaMm:number; spiralDiaMm:number; spiralSpacingIn:number; coverIn:number; wastePct:number; testCount:number };
type CapRow = { id:string; code:string; count:number; lengthFt:number; widthFt:number; thicknessIn:number; diaXmm:number; spacingXIn:number; diaYmm:number; spacingYIn:number; layers:number; wastePct:number };
type FootingRow = CapRow & { excavationDepthFt:number; workingSpaceFt:number; pccThicknessIn:number };
type RaftData = { lengthFt:number; widthFt:number; thicknessIn:number; excavationDepthFt:number; workingSpaceFt:number; sandFillIn:number; pccThicknessIn:number; diaXmm:number; spacingXIn:number; diaYmm:number; spacingYIn:number; layers:number; extraSteelKg:number; wastePct:number; waterproof:boolean };
type GradeBeamRow = { id:string; code:string; lengthFt:number; widthIn:number; depthIn:number; topBars:number; bottomBars:number; mainDiaMm:number; stirrupDiaMm:number; stirrupSpacingIn:number; coverIn:number; wastePct:number };
type GroundData = { lengthFt:number; widthFt:number; earthFillIn:number; sandFillIn:number; brickSoling:boolean; pccThicknessIn:number; slabThicknessIn:number; diaXmm:number; spacingXIn:number; diaYmm:number; spacingYIn:number; layers:number; wastePct:number };
type ColumnRow = { id:string; code:string; count:number; widthIn:number; depthIn:number; heightFt:number; mainBars:number; mainDiaMm:number; tieDiaMm:number; tieSpacingIn:number; coverIn:number; wastePct:number };
type BeamRow = { id:string; code:string; lengthFt:number; widthIn:number; depthIn:number; topBars:number; bottomBars:number; mainDiaMm:number; stirrupDiaMm:number; stirrupSpacingIn:number; coverIn:number; wastePct:number };
type SlabRow = { id:string; code:string; lengthFt:number; widthFt:number; thicknessIn:number; diaXmm:number; spacingXIn:number; diaYmm:number; spacingYIn:number; layers:number; wastePct:number };
type OtherRccRow = { id:string; item:string; concreteCft:number; steelKg:number; formworkSft:number };
type FinishRow = { id:string; item:string; unit:string; qty:number; materialRate:number; labourRate:number };
type Floor = { id:string; name:string; columns:ColumnRow[]; beams:BeamRow[]; slabs:SlabRow[]; other:OtherRccRow[]; finishes:FinishRow[] };

const money=(v:number)=>new Intl.NumberFormat("en-BD",{style:"currency",currency:"BDT",maximumFractionDigits:0}).format(Number.isFinite(v)?v:0);
const num=(v:number,d=2)=>new Intl.NumberFormat("en-BD",{maximumFractionDigits:d}).format(Number.isFinite(v)?v:0);
const uid=(p:string)=>`${p}-${Date.now()}-${Math.random().toString(36).slice(2,7)}`;
const patch=<T extends {id:string}>(rows:T[],id:string,change:Partial<T>)=>rows.map(r=>r.id===id?{...r,...change}:r);
const line=(section:string,subsection:string,item:string,unit:string,qty:number,rate:Rate):CostLine=>({section,subsection,item,unit,qty:safe(qty),materialRate:safe(rate.material),labourRate:safe(rate.labour),amount:amount(qty,rate.material,rate.labour)});

const initialRates:Rates={
  rcc:{label:"RCC concrete",unit:"cft",material:0,labour:0}, steel:{label:"Reinforcement steel",unit:"kg",material:0,labour:0}, formwork:{label:"Formwork",unit:"sft",material:0,labour:0},
  excavation:{label:"Earth excavation",unit:"cft",material:0,labour:0}, pcc:{label:"PCC / lean concrete",unit:"cft",material:0,labour:0}, backfill:{label:"Backfilling",unit:"cft",material:0,labour:0},
  earthFill:{label:"Earth filling",unit:"cft",material:0,labour:0}, sandFill:{label:"Sand filling",unit:"cft",material:0,labour:0}, brickSoling:{label:"Brick flat soling",unit:"sft",material:0,labour:0},
  boring:{label:"Pile boring",unit:"rft",material:0,labour:0}, pileHead:{label:"Pile head breaking",unit:"no",material:0,labour:0}, pileTest:{label:"Pile testing",unit:"no",material:0,labour:0}, waterproof:{label:"Waterproofing",unit:"sft",material:0,labour:0},
};
const newPreliminary=():PreliminaryItem=>({id:uid("pre"),item:"Custom preliminary item",unit:"LS",qty:1,materialRate:0,labourRate:0});
const initialPreliminary:PreliminaryItem[]=[
  {id:"pre-site",item:"Site clearing",unit:"LS",qty:1,materialRate:0,labourRate:0},{id:"pre-est",item:"Site establishment / temporary office",unit:"LS",qty:1,materialRate:0,labourRate:0},{id:"pre-survey",item:"Survey & setting out",unit:"LS",qty:1,materialRate:0,labourRate:0},{id:"pre-soil",item:"Soil test",unit:"LS",qty:1,materialRate:0,labourRate:0},{id:"pre-mob",item:"Mobilization",unit:"LS",qty:1,materialRate:0,labourRate:0},{id:"pre-safety",item:"Safety, barricading & temporary utilities",unit:"LS",qty:1,materialRate:0,labourRate:0},
];
const newPile=():PileRow=>({id:uid("pile"),code:"P1",count:1,diameterIn:20,lengthFt:50,mainBars:8,mainDiaMm:20,spiralDiaMm:10,spiralSpacingIn:6,coverIn:3,wastePct:5,testCount:0});
const newCap=():CapRow=>({id:uid("cap"),code:"PC-1",count:1,lengthFt:7,widthFt:7,thicknessIn:30,diaXmm:20,spacingXIn:6,diaYmm:20,spacingYIn:6,layers:1,wastePct:5});
const newFooting=():FootingRow=>({...newCap(),id:uid("ftg"),code:"F1",excavationDepthFt:5,workingSpaceFt:1,pccThicknessIn:3});
const initialRaft:RaftData={lengthFt:30,widthFt:40,thicknessIn:24,excavationDepthFt:4,workingSpaceFt:1,sandFillIn:6,pccThicknessIn:3,diaXmm:20,spacingXIn:6,diaYmm:20,spacingYIn:6,layers:2,extraSteelKg:0,wastePct:5,waterproof:false};
const newGradeBeam=():GradeBeamRow=>({id:uid("gb"),code:"GB-1",lengthFt:100,widthIn:12,depthIn:18,topBars:3,bottomBars:3,mainDiaMm:20,stirrupDiaMm:10,stirrupSpacingIn:6,coverIn:1.5,wastePct:5});
const initialGround:GroundData={lengthFt:40,widthFt:60,earthFillIn:12,sandFillIn:6,brickSoling:true,pccThicknessIn:3,slabThicknessIn:5,diaXmm:10,spacingXIn:6,diaYmm:10,spacingYIn:6,layers:1,wastePct:5};
const newColumn=():ColumnRow=>({id:uid("col"),code:"C1",count:1,widthIn:12,depthIn:20,heightFt:10,mainBars:8,mainDiaMm:20,tieDiaMm:10,tieSpacingIn:6,coverIn:1.5,wastePct:5});
const newBeam=():BeamRow=>({id:uid("beam"),code:"B1",lengthFt:100,widthIn:12,depthIn:18,topBars:3,bottomBars:3,mainDiaMm:20,stirrupDiaMm:10,stirrupSpacingIn:6,coverIn:1.5,wastePct:5});
const newSlab=():SlabRow=>({id:uid("slab"),code:"S1",lengthFt:40,widthFt:60,thicknessIn:5.5,diaXmm:10,spacingXIn:6,diaYmm:10,spacingYIn:6,layers:1,wastePct:5});
const newOther=():OtherRccRow=>({id:uid("other"),item:"Stair / shear wall / other RCC",concreteCft:0,steelKg:0,formworkSft:0});
const finishDefaults=():FinishRow[]=>[
  ["5 in brick wall","sft"],["10 in brick wall","sft"],["Internal wall plaster","sft"],["External wall plaster","sft"],["Ceiling plaster","sft"],["Floor tiles / finish","sft"],["Wall tiles","sft"],["Skirting","rft"],["Doors","no"],["Windows","sft"],["Interior paint","sft"],["Exterior paint","sft"],["Ceiling paint","sft"],["Waterproofing","sft"],["Railing","rft"],
].map(([item,unit],i)=>({id:`finish-${Date.now()}-${i}-${Math.random().toString(36).slice(2,5)}`,item,unit,qty:0,materialRate:0,labourRate:0}));
const newFloor=(name:string):Floor=>({id:uid("floor"),name,columns:[newColumn()],beams:[newBeam()],slabs:[newSlab()],other:[newOther()],finishes:finishDefaults()});

function NumberInput({value,onChange,step="0.01",min=0}:{value:number;onChange:(n:number)=>void;step?:string;min?:number}){return <input type="number" min={min} step={step} value={Number.isFinite(value)?value:0} onChange={e=>onChange(Number(e.target.value)||0)}/>}
function TextInput({value,onChange,placeholder}:{value:string;onChange:(v:string)=>void;placeholder?:string}){return <input value={value} placeholder={placeholder} onChange={e=>onChange(e.target.value)}/>}

export default function DetailedEstimateWorkspace(){
  const [step,setStep]=useState(1);
  const [projectName,setProjectName]=useState("");
  const [location,setLocation]=useState("");
  const [rates,setRates]=useState<Rates>(initialRates);
  const [preliminary,setPreliminary]=useState<PreliminaryItem[]>(initialPreliminary);
  const [foundationType,setFoundationType]=useState<"Pile Foundation"|"Raft Foundation"|"Isolated Footing">("Isolated Footing");
  const [piles,setPiles]=useState<PileRow[]>([newPile()]);
  const [caps,setCaps]=useState<CapRow[]>([newCap()]);
  const [footings,setFootings]=useState<FootingRow[]>([newFooting()]);
  const [raft,setRaft]=useState<RaftData>(initialRaft);
  const [gradeBeams,setGradeBeams]=useState<GradeBeamRow[]>([newGradeBeam()]);
  const [ground,setGround]=useState<GroundData>(initialGround);
  const [floors,setFloors]=useState<Floor[]>([newFloor("Ground Floor")]);
  const [activeFloor,setActiveFloor]=useState(0);
  const [floorTab,setFloorTab]=useState<"rcc"|"finish">("rcc");

  const rateCost=(qty:number,key:RateKey)=>amount(qty,rates[key].material,rates[key].labour);

  const preliminaryLines=useMemo<CostLine[]>(()=>preliminary.map(r=>({section:"01 Preliminary",subsection:"Preliminary Costing",item:r.item,unit:r.unit,qty:safe(r.qty),materialRate:safe(r.materialRate),labourRate:safe(r.labourRate),amount:amount(r.qty,r.materialRate,r.labourRate)})),[preliminary]);

  const foundationLines=useMemo<CostLine[]>(()=>{
    const out:CostLine[]=[];
    if(foundationType==="Pile Foundation"){
      piles.forEach(p=>{const q=pileQuantities(p);out.push(line("02 Foundation","Pile Work",`${p.code} · Boring`,"rft",q.boringRft,rates.boring),line("02 Foundation","Pile Work",`${p.code} · RCC concrete`,"cft",q.concreteCft,rates.rcc),line("02 Foundation","Pile Work",`${p.code} · Reinforcement`,"kg",q.steelKg,rates.steel),line("02 Foundation","Pile Work",`${p.code} · Pile head breaking`,"no",p.count,rates.pileHead));if(p.testCount>0)out.push(line("02 Foundation","Pile Work",`${p.code} · Pile testing`,"no",p.testCount,rates.pileTest));});
      caps.forEach(c=>{const q=footingQuantities({...c,excavationDepthFt:0,workingSpaceFt:0,pccThicknessIn:0});out.push(line("02 Foundation","Pile Cap",`${c.code} · RCC concrete`,"cft",q.concreteCft,rates.rcc),line("02 Foundation","Pile Cap",`${c.code} · Reinforcement`,"kg",q.steelKg,rates.steel),line("02 Foundation","Pile Cap",`${c.code} · Formwork`,"sft",q.formworkSft,rates.formwork));});
    }else if(foundationType==="Isolated Footing"){
      footings.forEach(f=>{const q=footingQuantities(f);out.push(line("02 Foundation","Isolated Footing",`${f.code} · Excavation`,"cft",q.excavationCft,rates.excavation),line("02 Foundation","Isolated Footing",`${f.code} · PCC`,"cft",q.pccCft,rates.pcc),line("02 Foundation","Isolated Footing",`${f.code} · RCC concrete`,"cft",q.concreteCft,rates.rcc),line("02 Foundation","Isolated Footing",`${f.code} · Reinforcement`,"kg",q.steelKg,rates.steel),line("02 Foundation","Isolated Footing",`${f.code} · Formwork`,"sft",q.formworkSft,rates.formwork),line("02 Foundation","Isolated Footing",`${f.code} · Backfilling`,"cft",q.backfillCft,rates.backfill));});
    }else{
      const area=raft.lengthFt*raft.widthFt;const excavation=(raft.lengthFt+2*raft.workingSpaceFt)*(raft.widthFt+2*raft.workingSpaceFt)*raft.excavationDepthFt;const sand=area*raft.sandFillIn/12;const pcc=area*raft.pccThicknessIn/12;const rcc=area*raft.thicknessIn/12;const mesh=meshSteelKg({lengthFt:raft.lengthFt,widthFt:raft.widthFt,diaXmm:raft.diaXmm,spacingXIn:raft.spacingXIn,diaYmm:raft.diaYmm,spacingYIn:raft.spacingYIn,layers:raft.layers,wastePct:raft.wastePct})+raft.extraSteelKg;const edge=2*(raft.lengthFt+raft.widthFt)*raft.thicknessIn/12;
      out.push(line("02 Foundation","Raft Foundation","Excavation","cft",excavation,rates.excavation),line("02 Foundation","Raft Foundation","Sand filling","cft",sand,rates.sandFill),line("02 Foundation","Raft Foundation","PCC","cft",pcc,rates.pcc),line("02 Foundation","Raft Foundation","RCC concrete","cft",rcc,rates.rcc),line("02 Foundation","Raft Foundation","Reinforcement","kg",mesh,rates.steel),line("02 Foundation","Raft Foundation","Edge formwork","sft",edge,rates.formwork));if(raft.waterproof)out.push(line("02 Foundation","Raft Foundation","Waterproofing","sft",area,rates.waterproof));
    }
    return out;
  },[foundationType,piles,caps,footings,raft,rates]);

  const gradeGroundLines=useMemo<CostLine[]>(()=>{
    const out:CostLine[]=[];gradeBeams.forEach(b=>{const q=beamQuantities(b);out.push(line("03 Grade Beam & Ground","Grade Beam",`${b.code} · RCC concrete`,"cft",q.concreteCft,rates.rcc),line("03 Grade Beam & Ground","Grade Beam",`${b.code} · Reinforcement`,"kg",q.steelKg,rates.steel),line("03 Grade Beam & Ground","Grade Beam",`${b.code} · Formwork`,"sft",q.formworkSft,rates.formwork));});
    const area=ground.lengthFt*ground.widthFt;const earth=area*ground.earthFillIn/12;const sand=area*ground.sandFillIn/12;const pcc=area*ground.pccThicknessIn/12;const slab=slabQuantities({lengthFt:ground.lengthFt,widthFt:ground.widthFt,thicknessIn:ground.slabThicknessIn,diaXmm:ground.diaXmm,spacingXIn:ground.spacingXIn,diaYmm:ground.diaYmm,spacingYIn:ground.spacingYIn,layers:ground.layers,wastePct:ground.wastePct});
    out.push(line("03 Grade Beam & Ground","Ground Preparation","Earth filling","cft",earth,rates.earthFill),line("03 Grade Beam & Ground","Ground Preparation","Sand filling","cft",sand,rates.sandFill));if(ground.brickSoling)out.push(line("03 Grade Beam & Ground","Ground Preparation","Brick flat soling","sft",area,rates.brickSoling));out.push(line("03 Grade Beam & Ground","Ground Preparation","PCC / lean concrete","cft",pcc,rates.pcc),line("03 Grade Beam & Ground","Ground Floor Slab","RCC concrete","cft",slab.concreteCft,rates.rcc),line("03 Grade Beam & Ground","Ground Floor Slab","Reinforcement","kg",slab.steelKg,rates.steel));return out;
  },[gradeBeams,ground,rates]);

  const floorGroups=useMemo(()=>floors.map(f=>{
    const rcc:CostLine[]=[];f.columns.forEach(c=>{const q=columnQuantities(c);rcc.push(line(`04 ${f.name}`,"RCC · Columns",`${c.code} · Concrete`,"cft",q.concreteCft,rates.rcc),line(`04 ${f.name}`,"RCC · Columns",`${c.code} · Reinforcement`,"kg",q.steelKg,rates.steel),line(`04 ${f.name}`,"RCC · Columns",`${c.code} · Formwork`,"sft",q.formworkSft,rates.formwork));});f.beams.forEach(b=>{const q=beamQuantities(b);rcc.push(line(`04 ${f.name}`,"RCC · Beams",`${b.code} · Concrete`,"cft",q.concreteCft,rates.rcc),line(`04 ${f.name}`,"RCC · Beams",`${b.code} · Reinforcement`,"kg",q.steelKg,rates.steel),line(`04 ${f.name}`,"RCC · Beams",`${b.code} · Formwork`,"sft",q.formworkSft,rates.formwork));});f.slabs.forEach(s=>{const q=slabQuantities(s);rcc.push(line(`04 ${f.name}`,"RCC · Slab",`${s.code} · Concrete`,"cft",q.concreteCft,rates.rcc),line(`04 ${f.name}`,"RCC · Slab",`${s.code} · Reinforcement`,"kg",q.steelKg,rates.steel),line(`04 ${f.name}`,"RCC · Slab",`${s.code} · Formwork`,"sft",q.formworkSft,rates.formwork));});f.other.forEach(o=>{if(o.concreteCft)rcc.push(line(`04 ${f.name}`,"RCC · Other",`${o.item} · Concrete`,"cft",o.concreteCft,rates.rcc));if(o.steelKg)rcc.push(line(`04 ${f.name}`,"RCC · Other",`${o.item} · Reinforcement`,"kg",o.steelKg,rates.steel));if(o.formworkSft)rcc.push(line(`04 ${f.name}`,"RCC · Other",`${o.item} · Formwork`,"sft",o.formworkSft,rates.formwork));});
    const finishing:CostLine[]=f.finishes.filter(x=>x.qty>0).map(x=>({section:`04 ${f.name}`,subsection:"Finishing",item:x.item,unit:x.unit,qty:safe(x.qty),materialRate:safe(x.materialRate),labourRate:safe(x.labourRate),amount:amount(x.qty,x.materialRate,x.labourRate)}));return {floor:f,rcc,finishing,lines:[...rcc,...finishing],rccTotal:rcc.reduce((s,x)=>s+x.amount,0),finishTotal:finishing.reduce((s,x)=>s+x.amount,0)};
  }),[floors,rates]);

  const allLines=useMemo(()=>[...preliminaryLines,...foundationLines,...gradeGroundLines,...floorGroups.flatMap(g=>g.lines)],[preliminaryLines,foundationLines,gradeGroundLines,floorGroups]);
  const totals=useMemo(()=>({preliminary:preliminaryLines.reduce((s,x)=>s+x.amount,0),foundation:foundationLines.reduce((s,x)=>s+x.amount,0),grade:gradeGroundLines.reduce((s,x)=>s+x.amount,0),floors:floorGroups.reduce((s,x)=>s+x.rccTotal+x.finishTotal,0),grand:allLines.reduce((s,x)=>s+x.amount,0)}),[preliminaryLines,foundationLines,gradeGroundLines,floorGroups,allLines]);
  const currentFloor=floors[Math.min(activeFloor,floors.length-1)];

  function updateRate(key:RateKey,field:"material"|"labour",value:number){setRates(r=>({...r,[key]:{...r[key],[field]:Math.max(0,value)}}));}
  function addFloor(){const n=floors.length;const name=n===1?"1st Floor":n===2?"2nd Floor":n===3?"3rd Floor":`${n}th Floor`;setFloors(v=>[...v,newFloor(name)]);setActiveFloor(floors.length);setFloorTab("rcc");}
  function copyFloor(){if(!currentFloor)return;const copied:Floor={...currentFloor,id:uid("floor"),name:`${currentFloor.name} Copy`,columns:currentFloor.columns.map(x=>({...x,id:uid("col")})),beams:currentFloor.beams.map(x=>({...x,id:uid("beam")})),slabs:currentFloor.slabs.map(x=>({...x,id:uid("slab")})),other:currentFloor.other.map(x=>({...x,id:uid("other")})),finishes:currentFloor.finishes.map(x=>({...x,id:uid("finish")}))};setFloors(v=>[...v,copied]);setActiveFloor(floors.length);}
  function removeFloor(){if(floors.length<=1||!currentFloor)return;setFloors(v=>v.filter(x=>x.id!==currentFloor.id));setActiveFloor(i=>Math.max(0,i-1));}
  function updateFloor(change:Partial<Floor>){if(!currentFloor)return;setFloors(v=>v.map((f,i)=>i===activeFloor?{...f,...change}:f));}
  const stepNames=["Preliminary","Foundation","Grade Beam & Ground","Floors","Detailed BOQ"];

  return <div className="de-page">
    <style>{`
      .de-page{color:#eef2f5}.de-head{display:flex;justify-content:space-between;gap:16px;align-items:flex-end;margin-bottom:16px}.de-head h1{font-size:34px;margin:4px 0}.de-head p{margin:0;color:#8d99a2;font-size:11px;line-height:1.6;max-width:760px}.de-actions{display:flex;gap:8px;flex-wrap:wrap}.de-btn{border:1px solid #394650;border-radius:8px;background:#17222b;color:#eef2f5;padding:9px 12px;font-size:10px;font-weight:900;cursor:pointer}.de-btn.red{background:#d61f26;border-color:#d61f26}.de-btn.ghost{background:transparent}.de-btn:disabled{opacity:.45;cursor:not-allowed}.de-project{display:grid;grid-template-columns:2fr 1fr;gap:10px;margin-bottom:12px}.de-card{border:1px solid #303b44;border-radius:12px;background:#101820;overflow:hidden}.de-card-head{padding:12px 14px;background:#17222b;border-bottom:2px solid #d61f26;display:flex;justify-content:space-between;gap:12px;align-items:center}.de-card-head small{color:#ef7771;font-size:8px;font-weight:900;letter-spacing:.12em;text-transform:uppercase}.de-card-head strong{display:block;margin-top:3px;font-size:14px}.de-body{padding:14px}.de-fields{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}.de-field{min-width:0}.de-field.span2{grid-column:span 2}.de-field label{display:block;margin:0 0 5px;color:#8f9ba5;font-size:8px;font-weight:900;text-transform:uppercase;letter-spacing:.05em}.de-field input,.de-field select,.de-table input,.de-table select{width:100%;box-sizing:border-box;border:1px solid #35414b;border-radius:7px;background:#0b1218;color:#eef2f5;padding:8px 9px;font-size:10px;outline:none}.de-field input:focus,.de-field select:focus,.de-table input:focus{border-color:#d61f26}.de-stepbar{display:grid;grid-template-columns:repeat(5,1fr);gap:6px;margin:12px 0}.de-step{border:1px solid #303b44;border-radius:9px;background:#101820;color:#8f9aa3;padding:10px;text-align:left;font-size:9px;font-weight:900;cursor:pointer}.de-step.active{background:#d61f26;border-color:#d61f26;color:#fff}.de-layout{display:grid;grid-template-columns:minmax(0,1fr) 265px;gap:12px;align-items:start}.de-side{position:sticky;top:12px}.de-metric{padding:12px 14px;border-bottom:1px solid #27323b}.de-metric span{display:block;color:#7f8c96;font-size:8px;font-weight:900;text-transform:uppercase}.de-metric strong{display:block;margin-top:5px;font-size:18px}.de-total strong{color:#ff8179;font-size:22px}.de-subtotal{display:flex;justify-content:space-between;gap:10px;padding:7px 0;border-bottom:1px solid #26313a;font-size:9px}.de-subtotal span{color:#8c98a2}.de-section-actions{display:flex;gap:6px;flex-wrap:wrap}.de-table-wrap{overflow:auto}.de-table{width:100%;border-collapse:collapse;min-width:980px}.de-table.compact{min-width:760px}.de-table th{padding:8px;background:#17222b;color:#87939d;text-align:left;font-size:8px;text-transform:uppercase;border-bottom:1px solid #3a454e}.de-table td{padding:7px;border-bottom:1px solid #27323b;font-size:9px;vertical-align:middle}.de-table .num{text-align:right}.de-table th.num{text-align:right}.de-table td input{min-width:74px}.de-table td.wide input{min-width:165px}.de-table button{white-space:nowrap}.de-note{padding:10px 12px;border-left:3px solid #d61f26;background:#131d25;color:#929fa8;font-size:9px;line-height:1.6}.de-note b{color:#eef2f5}.de-rate-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.de-rate{display:grid;grid-template-columns:minmax(0,1fr) 85px 85px;gap:6px;align-items:end;padding:8px;border:1px solid #2d3942;border-radius:8px}.de-rate b{font-size:9px}.de-rate small{display:block;margin-top:3px;color:#74818b;font-size:8px}.de-rate input{width:100%;box-sizing:border-box;border:1px solid #35414b;border-radius:6px;background:#0b1218;color:#eef2f5;padding:7px;font-size:9px}.de-rate label{font-size:7px;color:#7f8c96;text-transform:uppercase;font-weight:900}.de-spacer{height:10px}.de-floorbar{display:flex;gap:6px;align-items:center;flex-wrap:wrap;padding:10px 12px;border-bottom:1px solid #303b44}.de-floorbar select{min-width:180px;border:1px solid #35414b;border-radius:7px;background:#0b1218;color:#eef2f5;padding:8px}.de-tabs{display:flex;gap:6px}.de-tab{border:1px solid #37434c;background:#111a21;color:#9aa5ad;border-radius:7px;padding:8px 11px;font-size:9px;font-weight:900;cursor:pointer}.de-tab.active{background:#293640;color:#fff;border-color:#697984}.de-summary-row{display:grid;grid-template-columns:1fr auto;gap:10px;padding:9px 0;border-bottom:1px solid #27323b;font-size:10px}.de-summary-row span{color:#929da5}.de-summary-row.total{font-size:14px;border-bottom:0}.de-summary-row.total strong{color:#ff8179}.de-mobile-nav{display:none}.de-print-title{display:none}@media(max-width:1000px){.de-layout{grid-template-columns:1fr}.de-side{position:static}.de-fields{grid-template-columns:repeat(2,1fr)}.de-rate-grid{grid-template-columns:1fr}}@media(max-width:680px){.de-head{align-items:flex-start;flex-direction:column}.de-project{grid-template-columns:1fr}.de-fields{grid-template-columns:1fr}.de-field.span2{grid-column:auto}.de-stepbar{grid-template-columns:1fr 1fr}.de-stepbar .de-step:last-child{grid-column:1/-1}.de-actions{width:100%}.de-actions .de-btn{flex:1}.de-rate{grid-template-columns:1fr 78px 78px}}
      @media print{.masthead,.de-actions,.de-stepbar,.de-project,.de-side,.de-floorbar,.de-section-actions,.de-note,.de-no-print{display:none!important}.admin-main,.tmg-admin-main,.content-wrap,.tmg-content-wrap{margin:0!important;padding:0!important;max-width:none!important}.de-layout{display:block}.de-card{border:0!important;background:#fff!important;color:#111!important}.de-card-head{background:#eee!important;color:#111!important;border-color:#900!important}.de-table th{background:#eee!important;color:#111!important}.de-table td{color:#111!important;border-color:#ccc!important}.de-print-title{display:block!important;color:#111;margin-bottom:15px}.de-page{color:#111!important}}
    `}</style>

    <header className="de-head"><div><small style={{color:"#ef6c66",fontWeight:900,letterSpacing:".14em"}}>LAND VIEW / ESTIMATE &amp; COSTING</small><h1>Detailed Building Estimate</h1><p>Quantity-driven construction costing. Complete each stage in sequence; the detailed BOQ is generated automatically from the same entries.</p></div><div className="de-actions"><button className="de-btn" disabled>Summary Estimate · next phase</button><button className="de-btn red" onClick={()=>{setStep(5);setTimeout(()=>window.print(),50)}}>Print Detailed BOQ</button></div></header>

    <div className="de-project">
      <div className="de-card"><div className="de-card-head"><div><small>Project</small><strong>Estimate identity</strong></div></div><div className="de-body de-fields"><div className="de-field span2"><label>Project / Client Reference</label><TextInput value={projectName} onChange={setProjectName} placeholder="LV-#### · Client / project name"/></div><div className="de-field"><label>Location</label><TextInput value={location} onChange={setLocation} placeholder="Feni, Dhaka…"/></div><div className="de-field"><label>Foundation Type</label><select value={foundationType} onChange={e=>setFoundationType(e.target.value as typeof foundationType)}><option>Pile Foundation</option><option>Raft Foundation</option><option>Isolated Footing</option></select></div></div></div>
      <div className="de-card"><div className="de-card-head"><div><small>Current total</small><strong>{projectName||"Unassigned estimate"}</strong></div></div><div className="de-metric de-total"><span>Detailed construction cost</span><strong>{money(totals.grand)}</strong></div><div className="de-metric"><span>BOQ lines</span><strong>{allLines.filter(x=>x.qty>0).length}</strong></div></div>
    </div>

    <nav className="de-stepbar" aria-label="Detailed estimate stages">{stepNames.map((name,i)=><button key={name} className={`de-step ${step===i+1?"active":""}`} onClick={()=>setStep(i+1)}>{String(i+1).padStart(2,"0")} · {name}</button>)}</nav>

    <div className="de-layout"><main>
      {step===1&&<>
        <section className="de-card"><div className="de-card-head"><div><small>Step 01</small><strong>Preliminary Costing</strong></div><div className="de-section-actions"><button className="de-btn" onClick={()=>setPreliminary(v=>[...v,newPreliminary()])}>+ Add item</button></div></div><div className="de-table-wrap"><table className="de-table compact"><thead><tr><th>Item</th><th>Unit</th><th>Qty</th><th>Material Rate</th><th>Labour Rate</th><th className="num">Amount</th><th></th></tr></thead><tbody>{preliminary.map(r=><tr key={r.id}><td className="wide"><TextInput value={r.item} onChange={v=>setPreliminary(x=>patch(x,r.id,{item:v}))}/></td><td><TextInput value={r.unit} onChange={v=>setPreliminary(x=>patch(x,r.id,{unit:v}))}/></td><td><NumberInput value={r.qty} onChange={v=>setPreliminary(x=>patch(x,r.id,{qty:v}))}/></td><td><NumberInput value={r.materialRate} onChange={v=>setPreliminary(x=>patch(x,r.id,{materialRate:v}))}/></td><td><NumberInput value={r.labourRate} onChange={v=>setPreliminary(x=>patch(x,r.id,{labourRate:v}))}/></td><td className="num"><strong>{money(amount(r.qty,r.materialRate,r.labourRate))}</strong></td><td><button className="de-btn ghost" onClick={()=>setPreliminary(x=>x.filter(y=>y.id!==r.id))}>Remove</button></td></tr>)}</tbody></table></div></section>
        <div className="de-spacer"/>
        <section className="de-card"><div className="de-card-head"><div><small>Working rates</small><strong>Structural &amp; ground-work rate sheet</strong></div></div><div className="de-body"><div className="de-note"><b>Enter current rates once.</b> Structural calculations below use these material and labour rates automatically. A central LAND VIEW Rate Library can replace this manual rate sheet later.</div><div className="de-spacer"/><div className="de-rate-grid">{(Object.keys(rates) as RateKey[]).map(k=><div className="de-rate" key={k}><div><b>{rates[k].label}</b><small>per {rates[k].unit}</small></div><div><label>Material</label><NumberInput value={rates[k].material} onChange={v=>updateRate(k,"material",v)}/></div><div><label>Labour</label><NumberInput value={rates[k].labour} onChange={v=>updateRate(k,"labour",v)}/></div></div>)}</div></div></section>
      </>}

      {step===2&&<section className="de-card"><div className="de-card-head"><div><small>Step 02</small><strong>{foundationType} Costing</strong></div></div><div className="de-body de-no-print"><div className="de-field" style={{maxWidth:280}}><label>Foundation system</label><select value={foundationType} onChange={e=>setFoundationType(e.target.value as typeof foundationType)}><option>Pile Foundation</option><option>Raft Foundation</option><option>Isolated Footing</option></select></div></div>
        {foundationType==="Pile Foundation"&&<><div className="de-card-head"><div><small>Piles</small><strong>Pile types</strong></div><button className="de-btn" onClick={()=>setPiles(v=>[...v,newPile()])}>+ Add pile type</button></div><div className="de-table-wrap"><table className="de-table"><thead><tr><th>Code</th><th>No.</th><th>Dia in</th><th>Length ft</th><th>Main bars</th><th>Main dia mm</th><th>Spiral mm</th><th>Spacing in</th><th>Cover in</th><th>Waste %</th><th>Tests</th><th className="num">Concrete cft</th><th className="num">Steel kg</th><th></th></tr></thead><tbody>{piles.map(p=>{const q=pileQuantities(p);return <tr key={p.id}><td><TextInput value={p.code} onChange={v=>setPiles(x=>patch(x,p.id,{code:v}))}/></td><td><NumberInput value={p.count} step="1" onChange={v=>setPiles(x=>patch(x,p.id,{count:v}))}/></td><td><NumberInput value={p.diameterIn} onChange={v=>setPiles(x=>patch(x,p.id,{diameterIn:v}))}/></td><td><NumberInput value={p.lengthFt} onChange={v=>setPiles(x=>patch(x,p.id,{lengthFt:v}))}/></td><td><NumberInput value={p.mainBars} step="1" onChange={v=>setPiles(x=>patch(x,p.id,{mainBars:v}))}/></td><td><NumberInput value={p.mainDiaMm} onChange={v=>setPiles(x=>patch(x,p.id,{mainDiaMm:v}))}/></td><td><NumberInput value={p.spiralDiaMm} onChange={v=>setPiles(x=>patch(x,p.id,{spiralDiaMm:v}))}/></td><td><NumberInput value={p.spiralSpacingIn} onChange={v=>setPiles(x=>patch(x,p.id,{spiralSpacingIn:v}))}/></td><td><NumberInput value={p.coverIn} onChange={v=>setPiles(x=>patch(x,p.id,{coverIn:v}))}/></td><td><NumberInput value={p.wastePct} onChange={v=>setPiles(x=>patch(x,p.id,{wastePct:v}))}/></td><td><NumberInput value={p.testCount} step="1" onChange={v=>setPiles(x=>patch(x,p.id,{testCount:v}))}/></td><td className="num">{num(q.concreteCft)}</td><td className="num">{num(q.steelKg,1)}</td><td><button className="de-btn ghost" onClick={()=>setPiles(x=>x.filter(y=>y.id!==p.id))}>Remove</button></td></tr>})}</tbody></table></div>
        <div className="de-card-head"><div><small>Pile caps</small><strong>Pile-cap types</strong></div><button className="de-btn" onClick={()=>setCaps(v=>[...v,newCap()])}>+ Add cap type</button></div><div className="de-table-wrap"><table className="de-table"><thead><tr><th>Code</th><th>No.</th><th>L ft</th><th>W ft</th><th>T in</th><th>X dia</th><th>X sp.</th><th>Y dia</th><th>Y sp.</th><th>Layers</th><th>Waste %</th><th className="num">RCC cft</th><th className="num">Steel kg</th><th></th></tr></thead><tbody>{caps.map(c=>{const q=footingQuantities({...c,excavationDepthFt:0,workingSpaceFt:0,pccThicknessIn:0});return <tr key={c.id}><td><TextInput value={c.code} onChange={v=>setCaps(x=>patch(x,c.id,{code:v}))}/></td><td><NumberInput value={c.count} step="1" onChange={v=>setCaps(x=>patch(x,c.id,{count:v}))}/></td><td><NumberInput value={c.lengthFt} onChange={v=>setCaps(x=>patch(x,c.id,{lengthFt:v}))}/></td><td><NumberInput value={c.widthFt} onChange={v=>setCaps(x=>patch(x,c.id,{widthFt:v}))}/></td><td><NumberInput value={c.thicknessIn} onChange={v=>setCaps(x=>patch(x,c.id,{thicknessIn:v}))}/></td><td><NumberInput value={c.diaXmm} onChange={v=>setCaps(x=>patch(x,c.id,{diaXmm:v}))}/></td><td><NumberInput value={c.spacingXIn} onChange={v=>setCaps(x=>patch(x,c.id,{spacingXIn:v}))}/></td><td><NumberInput value={c.diaYmm} onChange={v=>setCaps(x=>patch(x,c.id,{diaYmm:v}))}/></td><td><NumberInput value={c.spacingYIn} onChange={v=>setCaps(x=>patch(x,c.id,{spacingYIn:v}))}/></td><td><NumberInput value={c.layers} step="1" onChange={v=>setCaps(x=>patch(x,c.id,{layers:v}))}/></td><td><NumberInput value={c.wastePct} onChange={v=>setCaps(x=>patch(x,c.id,{wastePct:v}))}/></td><td className="num">{num(q.concreteCft)}</td><td className="num">{num(q.steelKg,1)}</td><td><button className="de-btn ghost" onClick={()=>setCaps(x=>x.filter(y=>y.id!==c.id))}>Remove</button></td></tr>})}</tbody></table></div></>}
        {foundationType==="Isolated Footing"&&<><div className="de-card-head"><div><small>Footings</small><strong>Footing types</strong></div><button className="de-btn" onClick={()=>setFootings(v=>[...v,newFooting()])}>+ Add footing type</button></div><div className="de-table-wrap"><table className="de-table"><thead><tr><th>Code</th><th>No.</th><th>L ft</th><th>W ft</th><th>T in</th><th>Exc. depth</th><th>Work space</th><th>PCC in</th><th>X dia</th><th>X sp.</th><th>Y dia</th><th>Y sp.</th><th>Layers</th><th className="num">RCC cft</th><th className="num">Steel kg</th><th></th></tr></thead><tbody>{footings.map(f=>{const q=footingQuantities(f);return <tr key={f.id}><td><TextInput value={f.code} onChange={v=>setFootings(x=>patch(x,f.id,{code:v}))}/></td><td><NumberInput value={f.count} step="1" onChange={v=>setFootings(x=>patch(x,f.id,{count:v}))}/></td><td><NumberInput value={f.lengthFt} onChange={v=>setFootings(x=>patch(x,f.id,{lengthFt:v}))}/></td><td><NumberInput value={f.widthFt} onChange={v=>setFootings(x=>patch(x,f.id,{widthFt:v}))}/></td><td><NumberInput value={f.thicknessIn} onChange={v=>setFootings(x=>patch(x,f.id,{thicknessIn:v}))}/></td><td><NumberInput value={f.excavationDepthFt} onChange={v=>setFootings(x=>patch(x,f.id,{excavationDepthFt:v}))}/></td><td><NumberInput value={f.workingSpaceFt} onChange={v=>setFootings(x=>patch(x,f.id,{workingSpaceFt:v}))}/></td><td><NumberInput value={f.pccThicknessIn} onChange={v=>setFootings(x=>patch(x,f.id,{pccThicknessIn:v}))}/></td><td><NumberInput value={f.diaXmm} onChange={v=>setFootings(x=>patch(x,f.id,{diaXmm:v}))}/></td><td><NumberInput value={f.spacingXIn} onChange={v=>setFootings(x=>patch(x,f.id,{spacingXIn:v}))}/></td><td><NumberInput value={f.diaYmm} onChange={v=>setFootings(x=>patch(x,f.id,{diaYmm:v}))}/></td><td><NumberInput value={f.spacingYIn} onChange={v=>setFootings(x=>patch(x,f.id,{spacingYIn:v}))}/></td><td><NumberInput value={f.layers} step="1" onChange={v=>setFootings(x=>patch(x,f.id,{layers:v}))}/></td><td className="num">{num(q.concreteCft)}</td><td className="num">{num(q.steelKg,1)}</td><td><button className="de-btn ghost" onClick={()=>setFootings(x=>x.filter(y=>y.id!==f.id))}>Remove</button></td></tr>})}</tbody></table></div></>}
        {foundationType==="Raft Foundation"&&<div className="de-body"><div className="de-fields">{([ ["Length (ft)","lengthFt"],["Width (ft)","widthFt"],["Raft thickness (in)","thicknessIn"],["Excavation depth (ft)","excavationDepthFt"],["Working space (ft)","workingSpaceFt"],["Sand fill (in)","sandFillIn"],["PCC thickness (in)","pccThicknessIn"],["X bar dia (mm)","diaXmm"],["X spacing (in)","spacingXIn"],["Y bar dia (mm)","diaYmm"],["Y spacing (in)","spacingYIn"],["Mesh layers", "layers"],["Extra steel (kg)","extraSteelKg"],["Steel waste (%)","wastePct"] ] as [string,keyof RaftData][]).map(([labelText,key])=><div className="de-field" key={String(key)}><label>{labelText}</label><NumberInput value={Number(raft[key])||0} onChange={v=>setRaft(r=>({...r,[key]:v}))}/></div>)}<div className="de-field"><label>Waterproofing</label><select value={raft.waterproof?"Yes":"No"} onChange={e=>setRaft(r=>({...r,waterproof:e.target.value==="Yes"}))}><option>No</option><option>Yes</option></select></div></div></div>}
      </section>}

      {step===3&&<><section className="de-card"><div className="de-card-head"><div><small>Step 03A</small><strong>Grade Beam Costing</strong></div><button className="de-btn" onClick={()=>setGradeBeams(v=>[...v,newGradeBeam()])}>+ Add beam type</button></div><div className="de-table-wrap"><table className="de-table"><thead><tr><th>Code</th><th>Total L ft</th><th>W in</th><th>D in</th><th>Top bars</th><th>Bottom bars</th><th>Main mm</th><th>Stirrup mm</th><th>Spacing in</th><th>Cover in</th><th>Waste %</th><th className="num">RCC cft</th><th className="num">Steel kg</th><th></th></tr></thead><tbody>{gradeBeams.map(b=>{const q=beamQuantities(b);return <tr key={b.id}><td><TextInput value={b.code} onChange={v=>setGradeBeams(x=>patch(x,b.id,{code:v}))}/></td><td><NumberInput value={b.lengthFt} onChange={v=>setGradeBeams(x=>patch(x,b.id,{lengthFt:v}))}/></td><td><NumberInput value={b.widthIn} onChange={v=>setGradeBeams(x=>patch(x,b.id,{widthIn:v}))}/></td><td><NumberInput value={b.depthIn} onChange={v=>setGradeBeams(x=>patch(x,b.id,{depthIn:v}))}/></td><td><NumberInput value={b.topBars} step="1" onChange={v=>setGradeBeams(x=>patch(x,b.id,{topBars:v}))}/></td><td><NumberInput value={b.bottomBars} step="1" onChange={v=>setGradeBeams(x=>patch(x,b.id,{bottomBars:v}))}/></td><td><NumberInput value={b.mainDiaMm} onChange={v=>setGradeBeams(x=>patch(x,b.id,{mainDiaMm:v}))}/></td><td><NumberInput value={b.stirrupDiaMm} onChange={v=>setGradeBeams(x=>patch(x,b.id,{stirrupDiaMm:v}))}/></td><td><NumberInput value={b.stirrupSpacingIn} onChange={v=>setGradeBeams(x=>patch(x,b.id,{stirrupSpacingIn:v}))}/></td><td><NumberInput value={b.coverIn} onChange={v=>setGradeBeams(x=>patch(x,b.id,{coverIn:v}))}/></td><td><NumberInput value={b.wastePct} onChange={v=>setGradeBeams(x=>patch(x,b.id,{wastePct:v}))}/></td><td className="num">{num(q.concreteCft)}</td><td className="num">{num(q.steelKg,1)}</td><td><button className="de-btn ghost" onClick={()=>setGradeBeams(x=>x.filter(y=>y.id!==b.id))}>Remove</button></td></tr>})}</tbody></table></div></section><div className="de-spacer"/><section className="de-card"><div className="de-card-head"><div><small>Step 03B</small><strong>Ground Preparation &amp; Ground Floor Slab</strong></div></div><div className="de-body de-fields">{([ ["Ground length (ft)","lengthFt"],["Ground width (ft)","widthFt"],["Earth filling (in)","earthFillIn"],["Sand filling (in)","sandFillIn"],["PCC thickness (in)","pccThicknessIn"],["Floor slab thickness (in)","slabThicknessIn"],["X bar dia (mm)","diaXmm"],["X spacing (in)","spacingXIn"],["Y bar dia (mm)","diaYmm"],["Y spacing (in)","spacingYIn"],["Mesh layers", "layers"],["Steel waste (%)","wastePct"] ] as [string,keyof GroundData][]).map(([labelText,key])=><div className="de-field" key={String(key)}><label>{labelText}</label><NumberInput value={Number(ground[key])||0} onChange={v=>setGround(g=>({...g,[key]:v}))}/></div>)}<div className="de-field"><label>Brick flat soling</label><select value={ground.brickSoling?"Yes":"No"} onChange={e=>setGround(g=>({...g,brickSoling:e.target.value==="Yes"}))}><option>Yes</option><option>No</option></select></div></div></section></>}

      {step===4&&currentFloor&&<section className="de-card"><div className="de-card-head"><div><small>Step 04</small><strong>Floor-by-Floor RCC &amp; Finishing</strong></div></div><div className="de-floorbar"><select value={activeFloor} onChange={e=>setActiveFloor(Number(e.target.value))}>{floors.map((f,i)=><option value={i} key={f.id}>{f.name}</option>)}</select><div className="de-field" style={{minWidth:180}}><TextInput value={currentFloor.name} onChange={v=>updateFloor({name:v})}/></div><button className="de-btn" onClick={addFloor}>+ Add Floor</button><button className="de-btn" onClick={copyFloor}>Copy Floor</button><button className="de-btn ghost" onClick={removeFloor} disabled={floors.length<=1}>Remove Floor</button><div className="de-tabs"><button className={`de-tab ${floorTab==="rcc"?"active":""}`} onClick={()=>setFloorTab("rcc")}>RCC Estimate</button><button className={`de-tab ${floorTab==="finish"?"active":""}`} onClick={()=>setFloorTab("finish")}>Finishing Estimate</button></div></div>
        {floorTab==="rcc"&&<>
          <div className="de-card-head"><div><small>Columns</small><strong>Column schedule</strong></div><button className="de-btn" onClick={()=>updateFloor({columns:[...currentFloor.columns,newColumn()]})}>+ Column type</button></div><div className="de-table-wrap"><table className="de-table"><thead><tr><th>Code</th><th>No.</th><th>W in</th><th>D in</th><th>H ft</th><th>Main bars</th><th>Main mm</th><th>Tie mm</th><th>Tie sp.</th><th>Cover</th><th className="num">RCC cft</th><th className="num">Steel kg</th><th></th></tr></thead><tbody>{currentFloor.columns.map(c=>{const q=columnQuantities(c);return <tr key={c.id}><td><TextInput value={c.code} onChange={v=>updateFloor({columns:patch(currentFloor.columns,c.id,{code:v})})}/></td><td><NumberInput value={c.count} step="1" onChange={v=>updateFloor({columns:patch(currentFloor.columns,c.id,{count:v})})}/></td><td><NumberInput value={c.widthIn} onChange={v=>updateFloor({columns:patch(currentFloor.columns,c.id,{widthIn:v})})}/></td><td><NumberInput value={c.depthIn} onChange={v=>updateFloor({columns:patch(currentFloor.columns,c.id,{depthIn:v})})}/></td><td><NumberInput value={c.heightFt} onChange={v=>updateFloor({columns:patch(currentFloor.columns,c.id,{heightFt:v})})}/></td><td><NumberInput value={c.mainBars} step="1" onChange={v=>updateFloor({columns:patch(currentFloor.columns,c.id,{mainBars:v})})}/></td><td><NumberInput value={c.mainDiaMm} onChange={v=>updateFloor({columns:patch(currentFloor.columns,c.id,{mainDiaMm:v})})}/></td><td><NumberInput value={c.tieDiaMm} onChange={v=>updateFloor({columns:patch(currentFloor.columns,c.id,{tieDiaMm:v})})}/></td><td><NumberInput value={c.tieSpacingIn} onChange={v=>updateFloor({columns:patch(currentFloor.columns,c.id,{tieSpacingIn:v})})}/></td><td><NumberInput value={c.coverIn} onChange={v=>updateFloor({columns:patch(currentFloor.columns,c.id,{coverIn:v})})}/></td><td className="num">{num(q.concreteCft)}</td><td className="num">{num(q.steelKg,1)}</td><td><button className="de-btn ghost" onClick={()=>updateFloor({columns:currentFloor.columns.filter(x=>x.id!==c.id)})}>Remove</button></td></tr>})}</tbody></table></div>
          <div className="de-card-head"><div><small>Beams</small><strong>Beam schedule</strong></div><button className="de-btn" onClick={()=>updateFloor({beams:[...currentFloor.beams,newBeam()]})}>+ Beam type</button></div><div className="de-table-wrap"><table className="de-table"><thead><tr><th>Code</th><th>Total L ft</th><th>W in</th><th>D in</th><th>Top</th><th>Bottom</th><th>Main mm</th><th>Stirrup mm</th><th>Sp. in</th><th>Cover</th><th className="num">RCC cft</th><th className="num">Steel kg</th><th></th></tr></thead><tbody>{currentFloor.beams.map(b=>{const q=beamQuantities(b);return <tr key={b.id}><td><TextInput value={b.code} onChange={v=>updateFloor({beams:patch(currentFloor.beams,b.id,{code:v})})}/></td><td><NumberInput value={b.lengthFt} onChange={v=>updateFloor({beams:patch(currentFloor.beams,b.id,{lengthFt:v})})}/></td><td><NumberInput value={b.widthIn} onChange={v=>updateFloor({beams:patch(currentFloor.beams,b.id,{widthIn:v})})}/></td><td><NumberInput value={b.depthIn} onChange={v=>updateFloor({beams:patch(currentFloor.beams,b.id,{depthIn:v})})}/></td><td><NumberInput value={b.topBars} step="1" onChange={v=>updateFloor({beams:patch(currentFloor.beams,b.id,{topBars:v})})}/></td><td><NumberInput value={b.bottomBars} step="1" onChange={v=>updateFloor({beams:patch(currentFloor.beams,b.id,{bottomBars:v})})}/></td><td><NumberInput value={b.mainDiaMm} onChange={v=>updateFloor({beams:patch(currentFloor.beams,b.id,{mainDiaMm:v})})}/></td><td><NumberInput value={b.stirrupDiaMm} onChange={v=>updateFloor({beams:patch(currentFloor.beams,b.id,{stirrupDiaMm:v})})}/></td><td><NumberInput value={b.stirrupSpacingIn} onChange={v=>updateFloor({beams:patch(currentFloor.beams,b.id,{stirrupSpacingIn:v})})}/></td><td><NumberInput value={b.coverIn} onChange={v=>updateFloor({beams:patch(currentFloor.beams,b.id,{coverIn:v})})}/></td><td className="num">{num(q.concreteCft)}</td><td className="num">{num(q.steelKg,1)}</td><td><button className="de-btn ghost" onClick={()=>updateFloor({beams:currentFloor.beams.filter(x=>x.id!==b.id)})}>Remove</button></td></tr>})}</tbody></table></div>
          <div className="de-card-head"><div><small>Slabs</small><strong>Slab zones</strong></div><button className="de-btn" onClick={()=>updateFloor({slabs:[...currentFloor.slabs,newSlab()]})}>+ Slab zone</button></div><div className="de-table-wrap"><table className="de-table"><thead><tr><th>Code</th><th>L ft</th><th>W ft</th><th>T in</th><th>X dia</th><th>X sp.</th><th>Y dia</th><th>Y sp.</th><th>Layers</th><th>Waste %</th><th className="num">RCC cft</th><th className="num">Steel kg</th><th></th></tr></thead><tbody>{currentFloor.slabs.map(s=>{const q=slabQuantities(s);return <tr key={s.id}><td><TextInput value={s.code} onChange={v=>updateFloor({slabs:patch(currentFloor.slabs,s.id,{code:v})})}/></td><td><NumberInput value={s.lengthFt} onChange={v=>updateFloor({slabs:patch(currentFloor.slabs,s.id,{lengthFt:v})})}/></td><td><NumberInput value={s.widthFt} onChange={v=>updateFloor({slabs:patch(currentFloor.slabs,s.id,{widthFt:v})})}/></td><td><NumberInput value={s.thicknessIn} onChange={v=>updateFloor({slabs:patch(currentFloor.slabs,s.id,{thicknessIn:v})})}/></td><td><NumberInput value={s.diaXmm} onChange={v=>updateFloor({slabs:patch(currentFloor.slabs,s.id,{diaXmm:v})})}/></td><td><NumberInput value={s.spacingXIn} onChange={v=>updateFloor({slabs:patch(currentFloor.slabs,s.id,{spacingXIn:v})})}/></td><td><NumberInput value={s.diaYmm} onChange={v=>updateFloor({slabs:patch(currentFloor.slabs,s.id,{diaYmm:v})})}/></td><td><NumberInput value={s.spacingYIn} onChange={v=>updateFloor({slabs:patch(currentFloor.slabs,s.id,{spacingYIn:v})})}/></td><td><NumberInput value={s.layers} step="1" onChange={v=>updateFloor({slabs:patch(currentFloor.slabs,s.id,{layers:v})})}/></td><td><NumberInput value={s.wastePct} onChange={v=>updateFloor({slabs:patch(currentFloor.slabs,s.id,{wastePct:v})})}/></td><td className="num">{num(q.concreteCft)}</td><td className="num">{num(q.steelKg,1)}</td><td><button className="de-btn ghost" onClick={()=>updateFloor({slabs:currentFloor.slabs.filter(x=>x.id!==s.id)})}>Remove</button></td></tr>})}</tbody></table></div>
          <div className="de-card-head"><div><small>Other RCC</small><strong>Stairs, shear walls, lift core &amp; special items</strong></div><button className="de-btn" onClick={()=>updateFloor({other:[...currentFloor.other,newOther()]})}>+ Other RCC</button></div><div className="de-table-wrap"><table className="de-table compact"><thead><tr><th>Item</th><th>Concrete cft</th><th>Steel kg</th><th>Formwork sft</th><th className="num">Cost</th><th></th></tr></thead><tbody>{currentFloor.other.map(o=><tr key={o.id}><td className="wide"><TextInput value={o.item} onChange={v=>updateFloor({other:patch(currentFloor.other,o.id,{item:v})})}/></td><td><NumberInput value={o.concreteCft} onChange={v=>updateFloor({other:patch(currentFloor.other,o.id,{concreteCft:v})})}/></td><td><NumberInput value={o.steelKg} onChange={v=>updateFloor({other:patch(currentFloor.other,o.id,{steelKg:v})})}/></td><td><NumberInput value={o.formworkSft} onChange={v=>updateFloor({other:patch(currentFloor.other,o.id,{formworkSft:v})})}/></td><td className="num"><strong>{money(rateCost(o.concreteCft,"rcc")+rateCost(o.steelKg,"steel")+rateCost(o.formworkSft,"formwork"))}</strong></td><td><button className="de-btn ghost" onClick={()=>updateFloor({other:currentFloor.other.filter(x=>x.id!==o.id)})}>Remove</button></td></tr>)}</tbody></table></div>
        </>}
        {floorTab==="finish"&&<><div className="de-card-head"><div><small>Finishing</small><strong>{currentFloor.name} finishing schedule</strong></div><button className="de-btn" onClick={()=>updateFloor({finishes:[...currentFloor.finishes,{id:uid("finish"),item:"Custom finishing item",unit:"sft",qty:0,materialRate:0,labourRate:0}]})}>+ Custom item</button></div><div className="de-table-wrap"><table className="de-table compact"><thead><tr><th>Item</th><th>Unit</th><th>Qty</th><th>Material Rate</th><th>Labour Rate</th><th className="num">Amount</th><th></th></tr></thead><tbody>{currentFloor.finishes.map(r=><tr key={r.id}><td className="wide"><TextInput value={r.item} onChange={v=>updateFloor({finishes:patch(currentFloor.finishes,r.id,{item:v})})}/></td><td><TextInput value={r.unit} onChange={v=>updateFloor({finishes:patch(currentFloor.finishes,r.id,{unit:v})})}/></td><td><NumberInput value={r.qty} onChange={v=>updateFloor({finishes:patch(currentFloor.finishes,r.id,{qty:v})})}/></td><td><NumberInput value={r.materialRate} onChange={v=>updateFloor({finishes:patch(currentFloor.finishes,r.id,{materialRate:v})})}/></td><td><NumberInput value={r.labourRate} onChange={v=>updateFloor({finishes:patch(currentFloor.finishes,r.id,{labourRate:v})})}/></td><td className="num"><strong>{money(amount(r.qty,r.materialRate,r.labourRate))}</strong></td><td><button className="de-btn ghost" onClick={()=>updateFloor({finishes:currentFloor.finishes.filter(x=>x.id!==r.id)})}>Remove</button></td></tr>)}</tbody></table></div></>}
      </section>}

      {step===5&&<section className="de-card"><div className="de-print-title"><h1>LAND VIEW — Detailed Building Estimate</h1><p>{projectName||"Project"}{location?` · ${location}`:""}</p></div><div className="de-card-head"><div><small>Step 05</small><strong>Generated Detailed BOQ</strong></div></div><div className="de-table-wrap"><table className="de-table"><thead><tr><th>Section</th><th>Subsection</th><th>Item</th><th>Unit</th><th className="num">Qty</th><th className="num">Material Rate</th><th className="num">Labour Rate</th><th className="num">Total Rate</th><th className="num">Amount</th></tr></thead><tbody>{allLines.filter(x=>x.qty>0).map((r,i)=><tr key={`${r.section}-${r.item}-${i}`}><td>{r.section}</td><td>{r.subsection}</td><td>{r.item}</td><td>{r.unit}</td><td className="num">{num(r.qty)}</td><td className="num">{money(r.materialRate)}</td><td className="num">{money(r.labourRate)}</td><td className="num">{money(r.materialRate+r.labourRate)}</td><td className="num"><strong>{money(r.amount)}</strong></td></tr>)}{!allLines.some(x=>x.qty>0)&&<tr><td colSpan={9} style={{textAlign:"center",padding:30,color:"#87939d"}}>Enter quantities and rates in the previous steps to generate the BOQ.</td></tr>}</tbody></table></div><div className="de-body"><div className="de-summary-row"><span>Preliminary Costing</span><strong>{money(totals.preliminary)}</strong></div><div className="de-summary-row"><span>{foundationType}</span><strong>{money(totals.foundation)}</strong></div><div className="de-summary-row"><span>Grade Beam &amp; Ground Preparation</span><strong>{money(totals.grade)}</strong></div>{floorGroups.map(g=><div className="de-summary-row" key={g.floor.id}><span>{g.floor.name} · RCC {money(g.rccTotal)} + Finishing {money(g.finishTotal)}</span><strong>{money(g.rccTotal+g.finishTotal)}</strong></div>)}<div className="de-summary-row total"><span>Detailed Estimate Total</span><strong>{money(totals.grand)}</strong></div></div></section>}

      <section className="de-card de-summary-estimate">
        <div className="de-card-head">
          <div><small>CLIENT-FACING SUMMARY</small><strong>Summary Estimate</strong></div>
          <div style={{textAlign:"right"}}><small>PROJECT</small><strong>{projectName||"Project"}</strong></div>
        </div>
        <div className="de-body">
          <div className="de-note" style={{marginBottom:12}}>Automatically generated from the Detailed Estimate. No separate quantities or rates are required.</div>
          <div className="de-summary-row"><span>Preliminary Costing</span><strong>{money(totals.preliminary)}</strong></div>
          <div className="de-summary-row"><span>{foundationType}</span><strong>{money(totals.foundation)}</strong></div>
          <div className="de-summary-row"><span>Grade Beam &amp; Ground Preparation</span><strong>{money(totals.grade)}</strong></div>
          {floorGroups.map(g=><div className="de-summary-row" key={`summary-${g.floor.id}`}><span>{g.floor.name} · RCC + Finishing</span><strong>{money(g.rccTotal+g.finishTotal)}</strong></div>)}
          <div className="de-summary-row total"><span>Total Estimated Construction Cost</span><strong>{money(totals.grand)}</strong></div>
        </div>
      </section>

      <div className="de-spacer"/><div className="de-actions de-no-print" style={{justifyContent:"space-between"}}><button className="de-btn" disabled={step===1} onClick={()=>setStep(s=>Math.max(1,s-1))}>← Previous</button><button className="de-btn red" disabled={step===5} onClick={()=>setStep(s=>Math.min(5,s+1))}>Next →</button></div>
    </main>

    <aside className="de-card de-side"><div className="de-card-head"><div><small>Running cost</small><strong>Detailed estimate</strong></div></div><div className="de-body"><div className="de-subtotal"><span>Preliminary</span><strong>{money(totals.preliminary)}</strong></div><div className="de-subtotal"><span>Foundation</span><strong>{money(totals.foundation)}</strong></div><div className="de-subtotal"><span>Grade &amp; ground</span><strong>{money(totals.grade)}</strong></div><div className="de-subtotal"><span>All floors</span><strong>{money(totals.floors)}</strong></div></div><div className="de-metric de-total"><span>Grand total</span><strong>{money(totals.grand)}</strong></div><div className="de-body"><div className="de-note"><b>Detailed Estimate is the master calculation.</b> The Summary Estimate below is generated automatically from these same BOQ lines, so quantities and rates are entered only once.</div></div></aside>
    </div>
  </div>;
}
